<?php
namespace Modules\Glitter\Workflow\Jobs;
use Illuminate\Bus\Queueable;use Illuminate\Contracts\Queue\ShouldQueue;use Illuminate\Foundation\Bus\Dispatchable;use Illuminate\Queue\InteractsWithQueue;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Log;use Illuminate\Support\Str;use Modules\Glitter\Workflow\Enums\{AcceptanceStatus,WorkflowExecutionStatus,ActionExecutionStatus};use Modules\Glitter\Workflow\Models\{WorkflowAcceptance,Workflow,WorkflowExecution,WorkflowActionExecution};use Modules\Glitter\Workflow\Services\Runtime\ConditionEvaluator;use Modules\Glitter\Workflow\Jobs\ProcessWorkflowExecutionJob;
final class ProcessWorkflowAcceptanceJob implements ShouldQueue {use Dispatchable,InteractsWithQueue,Queueable;public int $tries=3;public int $timeout=30;public function __construct(public readonly string $acceptanceUuid){$this->afterCommit=true;}public function backoff():array{return [10,30,60];}public function handle(ConditionEvaluator $eval):void{$a=DB::transaction(function(){$a=WorkflowAcceptance::query()->where('uuid',$this->acceptanceUuid)->lockForUpdate()->first();if(!$a||$a->status===AcceptanceStatus::Processed)return null;if($a->status===AcceptanceStatus::Processing&&$a->claimed_at&&$a->claimed_at->gt(now()->subMinutes(10)))return null;$a->status=AcceptanceStatus::Processing;$a->attempts++;$a->claimed_at=now();$a->save();return $a;});if(!$a)return;try{$ctx=$a->trigger_context;$data=$ctx['data']??[];$works=Workflow::query()->where('trigger_key',$a->source_key)->where('is_active',true)->orderBy('id')->get();foreach($works as $w){try{if(!$eval->matches($w->condition_tree,$data))continue;DB::transaction(function()use($a,$w){$snap=['uuid'=>$w->uuid,'name'=>$w->name,'version'=>$w->version,'trigger_key'=>$w->trigger_key,'trigger_config'=>$w->trigger_config??[],'condition_tree'=>$w->condition_tree,'action_plan'=>$w->action_plan];$e=WorkflowExecution::query()->firstOrCreate(['acceptance_id'=>$a->id,'workflow_id'=>$w->id,'workflow_version'=>$w->version],['uuid'=>(string)Str::uuid(),'workflow_snapshot'=>$snap,'trigger_key'=>$w->trigger_key,'trigger_subject_type'=>$a->source_subject_type,'trigger_subject_id'=>$a->source_subject_id,'trigger_context'=>$a->trigger_context,'status'=>WorkflowExecutionStatus::Pending,'correlation_id'=>(string)Str::uuid(),'causation_id'=>null,'depth'=>0,'attempts'=>0]);if($e->wasRecentlyCreated){$e->correlation_id=$e->uuid;$e->save();foreach($w->action_plan as $i=>$item){WorkflowActionExecution::query()->create(['execution_id'=>$e->id,'action_index'=>$i,'action_type'=>$item['type'],'action_snapshot'=>$item,'config_hash'=>hash('sha256',json_encode($item)),'status'=>ActionExecutionStatus::Pending,'attempt_count'=>0,'idempotency_key'=>hash('sha256',$e->uuid.'|'.$i.'|'.$w->version)]);}} ProcessWorkflowExecutionJob::dispatch($e->uuid)->afterCommit();});}catch(\Throwable $x){Log::warning('Workflow definition skipped during planning',['workflow_uuid'=>$w->uuid,'error'=>$x->getMessage()]);}}$a->status=AcceptanceStatus::Processed;$a->processed_at=now();$a->save();}catch(\Throwable $e){$a->status=AcceptanceStatus::Failed;$a->last_error_code='planning_failed';$a->last_error_message=substr($e->getMessage(),0,1000);$a->save();throw $e;}}}
